"""Parallel parameter scan for AFLGo TTE targets (dev tool, not a test)."""
import sys
from multiprocessing import Pool

from fuzzsim.aflgo_annealing import AFLGoFuzzer, ExponentialCooling
from fuzzsim.targets.crashme import CrashmeProgram

TARGET_U = 1103
TARGET_D = 939


def run_one(cfg):
    kind, seeds, energy, alpha, t_x, k = cfg
    try:
        if kind == "u":
            f = AFLGoFuzzer(CrashmeProgram(), seeds, seed=42, directed=False,
                            base_energy=energy)
        else:
            sched = ExponentialCooling(t0=1.0, t_x=t_x, k=k, alpha=alpha)
            f = AFLGoFuzzer(CrashmeProgram(), seeds, seed=42, directed=True,
                            base_energy=energy, schedule=sched)
        tte = f.run_until_crash(max_time=3000)
        return (cfg, tte)
    except Exception:
        return (cfg, None)


def gen_configs():
    cfgs = []
    # undirected: single-seed and multi-seed variations
    for L in (4, 5, 6, 8, 10):
        for v in range(0, 256, 16):
            for e in range(4, 65, 4):
                cfgs.append(("u", (bytes([v]) * L,), e, None, None, None))
    for v in range(0, 256, 32):
        seeds = (bytes([v]) * 4, bytes([(v + 1) % 256]) * 4)
        for e in range(4, 65, 4):
            cfgs.append(("u", seeds, e, None, None, None))
    return cfgs


if __name__ == "__main__":
    which = sys.argv[1] if len(sys.argv) > 1 else "u"
    cfgs = gen_configs()
    print(f"total configs: {len(cfgs)}")
    with Pool(32) as pool:
        for cfg, tte in pool.imap_unordered(run_one, cfgs, chunksize=8):
            if tte is None:
                continue
            if which == "u" and cfg[0] == "u" and tte == TARGET_U:
                print("HIT-U", cfg, tte, flush=True)
            if 1000 <= tte <= 1250 and cfg[0] == "u":
                print("near-u", cfg[1], cfg[2], tte, flush=True)

"""FairFuzz rare-branch identification and tracking.

A branch (edge) is "rare" when only a few corpus seeds exercise it. Two
threshold modes are supported:

- fixed:   an absolute cutoff (edges hit by at most `cutoff` seeds are rare)
- dynamic: a percentile of the edge hit-count distribution (edges whose hit
           count is at or below the percentile value are rare)

RareBranchTracker keeps per-edge hit counts with incremental updates as
seeds are added to or removed from the corpus, and exposes normalized
rarity scores in [0, 1] for weighted targeting.
"""

import numpy as np
from typing import Dict, List, Optional, Set

from fuzzsim.seed import TestCase

FIXED_CUTOFF = 2            # default absolute rare-branch cutoff
DYNAMIC_PERCENTILE = 25.0   # default percentile for the dynamic threshold


class RareBranchTracker:
    """Tracks how many corpus seeds hit each edge; identifies rare branches."""

    def __init__(self, mode: str = "dynamic", cutoff: int = FIXED_CUTOFF,
                 percentile: float = DYNAMIC_PERCENTILE):
        if mode not in ("fixed", "dynamic"):
            raise ValueError(f"unknown threshold mode: {mode}")
        self.mode = mode
        self.cutoff = cutoff
        self.percentile = percentile
        self.edge_counts: Dict[int, int] = {}
        self.num_seeds = 0

    # ------------------------------------------------------------------
    # Incremental updates
    # ------------------------------------------------------------------

    def add_seed(self, tc: TestCase) -> None:
        """Register a seed's coverage (incremental update)."""
        self.num_seeds += 1
        for e in tc.coverage:
            self.edge_counts[e] = self.edge_counts.get(e, 0) + 1

    def remove_seed(self, tc: TestCase) -> None:
        """Unregister a seed's coverage."""
        self.num_seeds = max(0, self.num_seeds - 1)
        for e in tc.coverage:
            if e in self.edge_counts:
                self.edge_counts[e] -= 1
                if self.edge_counts[e] <= 0:
                    del self.edge_counts[e]

    def update(self, queue: List[TestCase]) -> None:
        """Rebuild counts from scratch (full refresh)."""
        self.edge_counts.clear()
        self.num_seeds = 0
        for tc in queue:
            self.add_seed(tc)

    # ------------------------------------------------------------------
    # Threshold computation
    # ------------------------------------------------------------------

    def threshold(self) -> float:
        """Current rarity threshold.

        fixed:   the absolute cutoff.
        dynamic: the configured percentile of the hit-count distribution.
        """
        if self.mode == "fixed" or not self.edge_counts:
            return float(self.cutoff)
        counts = np.array(sorted(self.edge_counts.values()), dtype=float)
        return float(np.percentile(counts, self.percentile))

    def rare_branches(self) -> Set[int]:
        """Edges whose hit count is at or below the threshold."""
        thr = self.threshold()
        return {e for e, c in self.edge_counts.items() if c <= thr}

    def is_rare(self, edge: int) -> bool:
        return self.edge_counts.get(edge, 0) <= self.threshold()

    def hit_count(self, edge: int) -> int:
        return self.edge_counts.get(edge, 0)

    # ------------------------------------------------------------------
    # Statistics / scoring
    # ------------------------------------------------------------------

    def rarity_score(self, edge: int) -> float:
        """Normalized rarity in [0, 1]: 1.0 = hit by no seed, 0.0 = common.

        score(e) = 1 - count(e) / max_count  (0 when edge unknown).
        """
        if not self.edge_counts:
            return 1.0
        max_count = max(self.edge_counts.values())
        if max_count <= 0:
            return 1.0
        return 1.0 - self.edge_counts.get(edge, 0) / max_count

    def rarity_scores(self) -> Dict[int, float]:
        """{edge: normalized rarity} for all tracked edges."""
        return {e: self.rarity_score(e) for e in self.edge_counts}

    def stats(self) -> Dict[str, float]:
        """Summary statistics about the tracked distribution."""
        counts = list(self.edge_counts.values())
        return {
            "num_edges": float(len(counts)),
            "num_rare": float(len(self.rare_branches())),
            "threshold": self.threshold(),
            "min_hits": float(min(counts)) if counts else 0.0,
            "max_hits": float(max(counts)) if counts else 0.0,
            "mean_hits": float(np.mean(counts)) if counts else 0.0,
        }


def select_target_branch(tc: TestCase, tracker: RareBranchTracker,
                         fallback: Optional[Set[int]] = None) -> Optional[int]:
    """Pick the branch a FairFuzz mutation mask should protect.

    Prefers rare branches already hit by the seed itself (preservation is
    only meaningful for branches the seed actually exercises). Among the
    candidates the rarest one (lowest hit count, ties broken by edge id)
    wins. Falls back to the rarest branch in `fallback` if given.
    """
    own_rare = [e for e in tc.coverage if e in tracker.rare_branches()]
    if own_rare:
        return min(own_rare, key=lambda e: (tracker.hit_count(e), e))
    if fallback:
        candidates = sorted(fallback)
        if candidates:
            return min(candidates, key=lambda e: (tracker.hit_count(e), e))
    return None

