    return cfgs


if __name__ == "__main__":
    cfgs = gen_configs()
    print(f"total configs: {len(cfgs)}", flush=True)
    hits = []
    with Pool(48) as pool:
        for cfg, tte in pool.imap_unordered(run_one, cfgs, chunksize=16):
            if tte == TARGET_U:
                print("HIT", cfg, flush=True)
                hits.append(cfg)
    print("done, hits:", hits)

